INSERT INTO T_STOCK_POST (
STOCK_ID
,USER_ID
,OPINION
,CONTENT
)
SELECT  S.ID
,#{userId}
,#{opinion}
,#{content}
FROM T_STOCK S
WHERE 1=1
AND S.ID = #{stockId}

mapper.update:
UPDATE T_STOCK_POST
SET DEL_DAY    = NOW()
,DEL_USERID = #{userId}
WHERE 1=1
AND ID      = #{postId}
AND DEL_DAY IS NULL

